const result = await model.doGenerate({
  prompt: [{ role: 'user', content: [{ type: 'text', text: 'hello' }] }],
  providerOptions: {
    providerName: {
      include: ['custom-field']
    }
  }
});
```

Or trigger automatic inclusion\:

```typescript
const result = await model.doGenerate({
  prompt: [{ role: 'user', content: [{ type: 'text', text: 'hello' }] }],
  providerOptions: {
    providerName: {
      reasoningEffort: 'high',
      store: false
