Or we could use TypeScript overloading to extend `combineHeaders` and support the optional parameter:

```typescript
type Header = Record<string, string | undefined>;

type CombineHeadersOptions = {
  mergeableKeys?: string[];
};

// Overload
export function combineHeaders(
  ...headers: Array<Header | undefined>
): Header;

export function combineHeaders(
  headers: Array<Header | undefined>,
  options: CombineHeadersOptions,
): Header;

export function combineHeaders(
  ...args: Array<Header | undefined> | [Array<Header | undefined>, CombineHeadersOptions]
): Header {
  let headers: Array<Header | undefined>;
  let options: CombineHeadersOptions;
  if (Array.isArray(args[0])) {
    headers = args[0];
    options = args[1] || {};
  } else {
    headers = args as Array<Header | undefined>;
    options = {};
  }

  return headers.reduce(
    (combinedHeaders, currentHeaders) => {
      if (!currentHeaders) return combinedHeaders;

      const result = { ...combinedHeaders };
      const mergeableLowerCaseKeys = options.mergeableKeys?.map(key => key.toLowerCase()) || [];

      for (const [key, value] of Object.entries(currentHeaders)) {
        if (value === undefined) continue;

        // Check if the key is mergeable (case-insensitive) and already exists
        if (mergeableLowerCaseKeys.includes(key.toLowerCase()) && result[key]) {
          const existingValues = result[key].split(',').map(val => val.trim());
          const newValues = value.split(',').map(val => val.trim());
          // Combine and deduplicate values
          const allValues = Array.from(new Set([...existingValues, ...newValues]));
          result[key] = allValues.join(',');
        } else {
          result[key] = value;
        }
      }

      return result;
    },
    {},
  ) as Record<string, string | undefined>;
}
```

However, I think it’s difficult to simplify it further for the following reasons:

- It needs to merge headers regardless of casing differences, such as `anthropic-beta` vs `Anthropic-Beta`.
- It needs to accept whitespace after commas, e.g., `anthropic-beta: feature1, feature2, feature3`.
- It needs to deduplicate values when merging, e.g., merging `anthropic-beta: feature1,feature2,feature3` with `anthropic-beta: feature2,feature3`.
- It needs to handle cases where both the header name and header value may be `undefined` in the original type definition.

