function createUiMessagesFromCapturedContent(content: unknown) {
  const interleavedAssistantParts = createInterleavedAssistantParts(content);

  return [
    {
      role: 'user',
      parts: [
        {
          type: 'text',
          text: 'Start the synthetic interleaved thinking repro.',
        },
      ],
    },
    {
      role: 'assistant',
      parts: interleavedAssistantParts,
    },
    {
      role: 'user',
      parts: [
        {
          type: 'text',
          text: 'Continue from the saved notes and summarize the result.',
        },
      ],
    },
  ] satisfies Array<Omit<UIMessage, 'id'>>;
}

function createInterleavedAssistantParts(content: unknown): UIMessage['parts'] {
  if (!Array.isArray(content)) {
    throw new Error('Captured content is not an array');
  }

  const reasoningParts = content
    .filter(
      part =>
        isRecord(part) &&
        part.type === 'reasoning' &&
        typeof part.text === 'string',
    )
    .slice(0, 2);
  const toolCall = content.find(
    part => isRecord(part) && part.type === 'tool-call',
  );

  if (reasoningParts.length < 2 || !isRecord(toolCall)) {
    throw new Error('Captured content needs two reasoning blocks and one tool call');
  }

  return [
    {
      type: 'reasoning',
      text: reasoningParts[0].text as string,
      state: 'done',
      providerMetadata: asProviderMetadata(reasoningParts[0].providerMetadata),
    },
    {
      type: 'tool-saveNote',
      state: 'output-available',
      toolCallId:
        typeof toolCall.toolCallId === 'string'
          ? toolCall.toolCallId
          : 'toolu_synthetic_1',
      input: { note: 'phase 1: initial plan' },
      output: { success: true },
    },
    {
      type: 'reasoning',
      text: reasoningParts[1].text as string,
      state: 'done',
      providerMetadata: asProviderMetadata(reasoningParts[1].providerMetadata),
    },
    {
      type: 'tool-saveNote',
      state: 'output-available',
      toolCallId: 'toolu_synthetic_2',
      input: { note: 'phase 2: revised plan' },
      output: { success: true },
    },
  ];
}

function getPartOrder(content: unknown): string[] {
  if (!Array.isArray(content)) {
    return [];
  }

  return content
    .map(part =>
      isRecord(part) && typeof part.type === 'string' ? part.type : undefined,
    )
    .filter((type): type is string => type != null);
}

function hasInterleavedThinking(order: string[]) {
  const firstReasoning = order.indexOf('reasoning');
  const secondReasoning = order.indexOf('reasoning', firstReasoning + 1);
  const toolCall = order.indexOf('tool-call', secondReasoning + 1);

  return firstReasoning !== -1 && secondReasoning !== -1 && toolCall !== -1;
}

function asProviderMetadata(
  value: unknown,
): SharedV4ProviderMetadata | undefined {
  return isRecord(value) ? (value as SharedV4ProviderMetadata) : undefined;
}

function getMessages(value: unknown): unknown {
  if (!isRecord(value)) {
    return undefined;
  }

  return value.messages;
}

function getMessageContentOrder(value: unknown) {
  const messages = getMessages(value);

  if (!Array.isArray(messages)) {
    return [];
  }

  return messages.map(message => {
    if (!isRecord(message)) {
      return message;
    }

    const content = message.content;

    return {
      role: message.role,
      content: Array.isArray(content)
        ? content.map(part =>
            isRecord(part) && typeof part.type === 'string'
              ? part.type
              : typeof part,
          )
        : typeof content,
    };
  });
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}
